"""
        Convert the test examples into Bert compatible format.
    """
def example_to_features_predict(
    input_ids: Any, attention_masks: Any, token_type_ids: Any
) -> object {
    return {
        "input_ids": input_ids,
        "attention_mask": attention_masks,
        "token_type_ids": token_type_ids
    };
}

